const root=new THREE.Group();scene.add(root);const actors=new THREE.Group();scene.add(actors);const decor=new THREE.Group();scene.add(decor);
const mat=(color,rough=.8,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const stone=mat(0x555057),stoneLight=mat(0x736658),darkStone=mat(0x292a30),floorMat=mat(0x443b39),trim=mat(0x9b805f,.66),gold=mat(0xe4b55f,.42,.55),emberMat=new THREE.MeshStandardMaterial({color:0xff6937,emissive:0xff3d16,emissiveIntensity:2,roughness:.5}),blueMat=new THREE.MeshStandardMaterial({color:0x93d8ff,emissive:0x3799d9,emissiveIntensity:1.9,roughness:.35});
const box=(group,x,y,z,sx,sy,sz,material)=>{const o=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;group.add(o);return o};
const cylinder=(group,x,y,z,r1,r2,h,material,seg=10)=>{const o=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,seg),material);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;group.add(o);return o};
const sphere=(group,x,y,z,r,material,seg=12)=>{const o=new THREE.Mesh(new THREE.SphereGeometry(r,seg,seg),material);o.position.set(x,y,z);o.castShadow=true;group.add(o);return o};
const floor=box(root,0,-.3,0,13,.5,13,floorMat); floor.castShadow=false;
// Inlaid chamber floor
for(let i=-5;i<=5;i++)for(let j=-5;j<=5;j++){if((i+j)%2===0){const tile=box(root,i,-.038,j,.97,.035,.97,(i%3===0&&j%3===0)?stone:darkStone);tile.castShadow=false}}
const rim=mat(0x826d59,.76); for(let side of [-1,1]){box(root,side*6.45,.03,0,.24,.28,13,rim);box(root,0,.03,side*6.45,13,.28,.24,rim)}
// Vault walls with chunky masonry and deep arch-like openings
for(let x=-5.5;x<=5.5;x+=1.55){if(Math.abs(x)<1.9)continue;box(root,x,1.05,-6.25,1.48,2.1,.55,stone);box(root,x,.15,-5.92,1.48,.16,.18,trim);box(root,x,2.12,-6.13,1.52,.23,.74,stoneLight)}
// Back arch pillars and lintel
for(let x of [-1.9,1.9]){box(root,x,1.35,-6.25,.34,2.7,.58,stoneLight);box(root,x,2.75,-6.2,.56,.27,.76,trim)}box(root,0,3.12,-6.23,4.15,.42,.72,stoneLight);
for(let side of [-1,1]){for(let z=-5;z<=5;z+=1.6){box(root,side*6.18,1,z,.5,2,.56,stone);box(root,side*6.18,2.02,z,.62,.22,.65,stoneLight)}box(root,side*6.18,1,-1.7,.59,2.2,.7,trim)}
// shallow stair of the sealed inner doorway
for(let i=0;i<3;i++){box(root,0,.05+i*.13,-5.3-i*.36,2.3,.24,.54,stoneLight)}
// carved columns, wall torches and rune details
