const torches=[];for(let x of [-5.6,-2.7,2.7,5.6]){box(decor,x,1.45,-5.75,.12,.58,.12,darkStone);sphere(decor,x,1.9,-5.68,.14,emberMat);const p=new THREE.PointLight(0xff713b,18,5);p.position.set(x,2,-5.35);scene.add(p);torches.push({mesh:decor.children[decor.children.length-1],light:p,phase:Math.random()*6})}
// Central floor sigil (raised bronze circular inlay)
const sigilMat=new THREE.MeshStandardMaterial({color:0x927752,metalness:.65,roughness:.42});const ring=new THREE.Mesh(new THREE.TorusGeometry(1.7,.035,8,64),sigilMat);ring.rotation.x=Math.PI/2;ring.position.y=-.018;root.add(ring);const ring2=new THREE.Mesh(new THREE.TorusGeometry(1.25,.023,8,48),sigilMat);ring2.rotation.x=Math.PI/2;ring2.position.y=-.015;root.add(ring2);
for(let i=0;i<8;i++){const a=i*Math.PI/4;const rune=box(root,Math.cos(a)*1.48,.005,Math.sin(a)*1.48,.18,.018,.045,gold);rune.rotation.y=-a}
// rubble clusters
for(const [x,z,s] of [[-4,-3,.75],[4,-3,.65],[-4.5,2.7,.8],[4.4,2.8,.65],[-2.8,4.5,.5],[3.1,4.8,.6]]){for(let k=0;k<4;k++){const r=box(decor,x+(Math.random()-.5)*s,.08+Math.random()*.15,z+(Math.random()-.5)*s,s*(.3+Math.random()*.5),.18+Math.random()*.2,s*(.3+Math.random()*.5),k%2?stone:stoneLight);r.rotation.y=Math.random()*2;r.rotation.x=(Math.random()-.5)*.12}}
// distant spectral opening
const portalMat=new THREE.MeshBasicMaterial({color:0x6357a8,transparent:true,opacity:.2,side:THREE.DoubleSide});const portal=new THREE.Mesh(new THREE.CircleGeometry(1.2,32),portalMat);portal.position.set(0,1.7,-5.84);root.add(portal);const portalRing=new THREE.Mesh(new THREE.TorusGeometry(1.35,.055,10,40),new THREE.MeshStandardMaterial({color:0x8977c1,emissive:0x352166,emissiveIntensity:1.2,metalness:.4}));portalRing.position.set(0,1.7,-5.75);root.add(portalRing);
// Player character, hand-built low-poly armored adventurer
const player=new THREE.Group();actors.add(player);const playerBody=new THREE.Group();player.add(playerBody);
const cloak=mat(0x493d55),tunic=mat(0x82704f),skin=mat(0xd0a47d),leather=mat(0x382e2b),steel=mat(0xabb9bd,.34,.72),hair=mat(0x33262b);
cylinder(playerBody,0,.23,0,.38,.35,.32,leather,8);const torso=cylinder(playerBody,0,.79,0,.34,.43,.84,tunic,7);torso.rotation.z=Math.PI;
cylinder(playerBody,0,.83,0,.32,.35,.4,cloak,7);sphere(playerBody,0,1.42,0,.27,skin,10);const hood=sphere(playerBody,0,1.53,-.075,.32,cloak,8);hood.scale.set(1,.95,.9);
const helm= new THREE.Mesh(new THREE.ConeGeometry(.29,.48,7),steel);helm.position.set(0,1.76,0);helm.castShadow=true;playerBody.add(helm);
for(let s of [-1,1]){const arm=cylinder(playerBody,s*.42,.83,0,.14,.12,.62,cloak,7);arm.rotation.z=s*.35;const hand=sphere(playerBody,s*.5,.49,.02,.12,skin,8);const leg=cylinder(playerBody,s*.18,.25,.02,.16,.14,.44,leather,7);leg.rotation.z=s*.05}
// sword pivot at the right side
const swordPivot=new THREE.Group();swordPivot.position.set(.49,.65,0);playerBody.add(swordPivot);const blade=box(swordPivot,.14,.38,.05,.13,.72,.055,steel);blade.rotation.z=-.12;const guard=box(swordPivot,.13,.09,.05,.38,.08,.11,gold);const grip=cylinder(swordPivot,.13,-.1,.05,.055,.05,.22,leather,8);const pom=sphere(swordPivot,.13,-.23,.05,.075,gold,8);swordPivot.rotation.z=-.8;
// enemy models
const enemies=[];const enemySpecs=[['Cinderling',0x9e5140,32,8,1.2],['Bone Warden',0xc2b599,48,10,1.35],['Gloom Stalker',0x61547e,60,12,1.5],['Ash Knight',0x977044,82,14,1.75],['The Hollow King',0x9c5e87,118,17,2.1]];
function makeEnemy(type,index){const g=new THREE.Group();actors.add(g);const [name,color,hp,damage,size]=enemySpecs[(index-1)%5];const bodymat=mat(color,.62);const dark=mat(0x342c36);const glow=new THREE.MeshStandardMaterial({color:0xffa45b,emissive:0xff4821,emissiveIntensity:2.4});
if(index===2){ // bone-woven brute
 cylinder(g,0,.65,0,.48,.55,.72,bodymat,8);sphere(g,0,1.22,0,.36,mat(0xbdb6a4),8);for(let s of [-1,1]){sphere(g,s*.13,1.28,.31,.065,glow,8);const horn=new THREE.Mesh(new THREE.ConeGeometry(.11,.38,6),mat(0xddd0b0));horn.position.set(s*.23,1.53,0);horn.rotation.z=-s*.55;g.add(horn);cylinder(g,s*.52,.6,0,.2,.17,.69,bodymat,7)}
}else if(index===3){cylinder(g,0,.55,0,.35,.45,.68,bodymat,7);sphere(g,0,1.08,0,.3,bodymat,8);for(let s of [-1,1]){sphere(g,s*.12,1.1,.27,.065,glow,8);const wing=box(g,s*.57,.76,-.07,.62,.57,.13,bodymat);wing.rotation.z=s*.65}cylinder(g,0,.05,0,.4,.32,.2,dark,8)
}else{cylinder(g,0,.59,0,.42,.5,.75,bodymat,8);sphere(g,0,1.13,0,.34,bodymat,8);for(let s of [-1,1]){sphere(g,s*.14,1.18,.29,.07,glow,8);cylinder(g,s*.5,.57,0,.2,.18,.62,bodymat,7);const horn=new THREE.Mesh(new THREE.ConeGeometry(.12,.35,6),bodymat);horn.position.set(s*.21,1.47,-.02);horn.rotation.z=-s*.35;g.add(horn)}}
const shadow=new THREE.Mesh(new THREE.CircleGeometry(.55,18),new THREE.MeshBasicMaterial({color:0x0b0b10,transparent:true,opacity:.45}));shadow.rotation.x=-Math.PI/2;shadow.position.y=.006;g.add(shadow);
g.scale.setScalar(size);return {group:g,name,hp,maxHp:hp,damage,phase:Math.random()*6,attackTimer:1.4,index,alive:true,glow};}
let room=1,clears=0,kills=0,maxHp=100,hp=100,coins=24,level=1,xp=34,power=12,armor=4,basePower=12,moveSpeed=4.5,roomEnemies=3,attackCD=0,dashCD=0,burstCD=0,attackAnim=0,playerInvuln=0,animTime=0,gameStarted=false,paused=false,roomReady=false;
let move={x:0,z:0},joystickTouch=null,keys={},lastTime=performance.now(),lootChoice=null;
const roomNames=['Ashen Antechamber','The Bone Gallery','Veil of Whispers','The Cinder Vault','Throne of Embers'];
const items=[
 {name:'Emberfang',icon:'⚔',type:'weapon',power:5,desc:'+5 weapon power',rarity:'RARE'},
 {name:'Warden’s Mantle',icon:'♜',type:'armor',armor:4,desc:'+4 armor',rarity:'RARE'},
 {name:'Ashen Heart',icon:'♥',type:'charm',hp:25,desc:'+25 max vitality',rarity:'RARE'},
 {name:'Moonsteel Edge',icon:'✧',type:'weapon',power:8,desc:'+8 weapon power',rarity:'EPIC'},
 {name:'Cinder Ward',icon:'⬡',type:'armor',armor:7,desc:'+7 armor',rarity:'EPIC'},
 {name:'Phoenix Sigil',icon:'◈',type:'charm',heal:35,desc:'Restore 35 vitality',rarity:'EPIC'},
 {name:'Voidcleaver',icon:'☄',type:'weapon',power:12,desc:'+12 weapon power',rarity:'LEGENDARY'},
 {name:'King’s Aegis',icon:'♜',type:'armor',armor:10,desc:'+10 armor',rarity:'LEGENDARY'},
 {name:'Everflame Loop',icon:'✹',type:'charm',power:3,hp:20,desc:'+3 power · +20 vitality',rarity:'LEGENDARY'}
];
let equipped={weapon:'⚔',armor:'♜',charm:'◈'};
function updateHUD(){ $('depth').textContent=String(room).padStart(2,'0');$('room-num').textContent=room;$('room-name').textContent=roomNames[(room-1)%5];$('coins').textContent=coins;$('level').textContent=String(level).padStart(2,'0');$('xp-level').textContent=String(level).padStart(2,'0');$('power').textContent=power;$('armor').textContent=armor;$('hp-text').textContent=Math.ceil(hp);$('hp-fill').style.width=`${Math.max(0,hp/maxHp*100)}%`;$('xp-text').textContent=`${xp} / ${100+(level-1)*60} XP`;$('xp-fill').style.width=`${Math.min(100,xp/(100+(level-1)*60)*100)}%`;$('weapon-icon').textContent=equipped.weapon;$('armor-icon').textContent=equipped.armor;$('accessory-icon').textContent=equipped.charm;$('kill-count').textContent=`${kills} / ${roomEnemies}`;$('quest-fill').style.width=`${Math.min(100,kills/roomEnemies*100)}%`;}
function showToast(t){$('toast').textContent=t;$('toast').classList.add('visible');setTimeout(()=>$('toast').classList.remove('visible'),1900)}
function spawnEnemy(index=room){const e=makeEnemy('enemy',index);let angle=Math.random()*Math.PI*2,r=2+Math.random()*2.2;e.group.position.set(Math.cos(angle)*r,0,Math.sin(angle)*r-0.1);e.attackTimer=.8+Math.random()*1.5;enemies.push(e);return e}
function setEnemyCard(e){if(!e||!e.alive){$('enemy-card').classList.remove('show');return}$('enemy-card').classList.add('show');$('enemy-name').textContent=e.name;$('enemy-rank').textContent=(e.index===5?'BOSS':'BEAST')+' · LV '+e.index;$('enemy-fill').style.width=`${Math.max(0,e.hp/e.maxHp*100)}%`;$('enemy-hp-text').textContent=`${Math.ceil(e.hp)} / ${e.maxHp}`}
function chooseTarget(){let live=enemies.filter(e=>e.alive);if(!live.length)return null;live.sort((a,b)=>a.group.position.distanceTo(player.position)-b.group.position.distanceTo(player.position));return live[0]}
function damageEnemy(e,n,kind='hit'){if(!e||!e.alive)return;e.hp-=n;const log=$('combat-log');log.textContent=kind==='burst'?'✧ '+n:'-'+n;log.classList.remove('show');void log.offsetWidth;log.classList.add('show');e.group.scale.setScalar(e.group.scale.x*.88);setTimeout(()=>{if(e.alive)e.group.scale.setScalar(enemySpecs[(e.index-1)%5][4])},100);setEnemyCard(e);if(e.hp<=0){e.alive=false;actors.remove(e.group);kills++;clears++;const reward=9+room*3;coins+=reward;xp+=28+room*8;while(xp>=100+(level-1)*60){xp-=100+(level-1)*60;level++;power+=2;maxHp+=8;hp=Math.min(maxHp,hp+30);showToast(`LEVEL UP · ${level}`)}updateHUD();$('quest-copy').textContent=kills>=roomEnemies?'The last creature falls. Choose your reward.':'A creature falls. Stay alert — more are near.';if(kills>=roomEnemies)completeRoom();else{let next=enemies.find(x=>x.alive);setEnemyCard(next)}}}
function attack(){if(!gameStarted||paused||!roomReady||attackCD>0)return;const e=chooseTarget();attackCD=.46;attackAnim=.33;playerInvuln=Math.max(playerInvuln,.13);if(e){const dist=e.group.position.distanceTo(player.position);if(dist<3.35){const facing=new THREE.Vector3(Math.sin(player.rotation.y),0,Math.cos(player.rotation.y));const to=e.group.position.clone().sub(player.position).normalize();if(facing.dot(to)<-.2)player.rotation.y=Math.atan2(to.x,to.z);damageEnemy(e,power+Math.floor(Math.random()*5),'hit')}}}
function burst(){if(!gameStarted||paused||!roomReady||burstCD>0)return;burstCD=8;const ball=new THREE.Mesh(new THREE.SphereGeometry(.55,16,12),new THREE.MeshBasicMaterial({color:0xffa348,transparent:true,opacity:.75}));ball.position.copy(player.position);ball.position.y=.7;scene.add(ball);const targetScale=3.4;let age=0;function pulse(){age+=.04;ball.scale.setScalar(1+age*7);ball.material.opacity=Math.max(0,.75-age*.65);if(age<.4)requestAnimationFrame(pulse);else scene.remove(ball)}pulse();for(const e of enemies)if(e.alive&&e.group.position.distanceTo(player.position)<4.4)damageEnemy(e,Math.floor(power*1.65)+6,'burst');showToast('EMBER BURST')}
function dash(){if(!gameStarted||paused||!roomReady||dashCD>0)return;dashCD=3;let dx=move.x,dz=move.z;if(Math.hypot(dx,dz)<.1){dx=Math.sin(player.rotation.y);dz=Math.cos(player.rotation.y)}player.position.x+=dx*1.35;player.position.z+=dz*1.35;player.position.x=THREE.MathUtils.clamp(player.position.x,-5.4,5.4);player.position.z=THREE.MathUtils.clamp(player.position.z,-5.25,5.3);playerInvuln=.45;playerBody.position.y=.2;setTimeout(()=>playerBody.position.y=0,190);showToast('DASH')}
function renderCooldown(btn,sec){const b=$(btn),cd=b.querySelector('.cooldown');if(sec>0){b.classList.add('cooling');cd.querySelector('b').textContent=Math.ceil(sec)}else b.classList.remove('cooling')}
function completeRoom(){roomReady=false;paused=true;$('enemy-card').classList.remove('show');$('quest-badge').textContent='CLEARED';$('quest-badge').style.color='#f1d48d';$('quest-copy').textContent='The ancient seal releases. Take a relic before descending deeper.';const pool=room===5?[items[6],items[7],items[8]]:room===4?[items[3],items[4],items[8]]:room===3?[items[0],items[1],items[5]]:[items[0],items[1],items[2],items[3],items[4],items[5]];const options=[...pool].sort(()=>Math.random()-.5).slice(0,3);$('loot-title').textContent=room===5?'The king’s final legacy':'A relic from the ashes';$('loot-cards').innerHTML=options.map((it,i)=>`<button class="loot-option" data-idx="${i}"><div class="item-icon">${it.icon}</div><b>${it.name}</b><span>${it.desc}</span><em>${it.rarity}</em></button>`).join('');lootChoice=null;document.querySelectorAll('.loot-option').forEach((el,i)=>el.onclick=()=>{document.querySelectorAll('.loot-option').forEach(x=>x.style.borderColor='');el.style.borderColor='#e2bf7b';lootChoice=options[i]});$('loot-overlay').classList.remove('hidden')}
function applyLoot(it){if(!it)return;const n=it.type;if(n==='weapon'){power+=it.power;equipped.weapon=it.icon}else if(n==='armor'){armor+=it.armor;equipped.armor=it.icon}else if(n==='charm'){equipped.charm=it.icon;if(it.power)power+=it.power;if(it.hp){maxHp+=it.hp;hp+=it.hp}if(it.heal)hp=Math.min(maxHp,hp+it.heal)}updateHUD();showToast(`${it.name} EQUIPPED`)}
function nextRoom(){if(!lootChoice){showToast('Choose a relic to continue');return}applyLoot(lootChoice);$('loot-overlay').classList.add('hidden');if(room>=5){$('end-overlay').classList.remove('hidden');return}room++;roomEnemies=room===5?1:2+Math.min(room-1,2);kills=0;roomReady=true;paused=false;$('quest-badge').textContent='IN PROGRESS';$('quest-badge').style.color='';$('quest-title').textContent=room===5?'Defeat the Hollow King':'Clear the chamber';$('quest-copy').textContent='A deeper darkness gathers. Defeat every creature to reveal the way onward.';updateHUD();for(let i=0;i<roomEnemies;i++)spawnEnemy(room);setEnemyCard(chooseTarget());showToast(`${roomNames[(room-1)%5]} · ENTERED`)}
function resetGame(){for(const e of enemies)actors.remove(e.group);enemies.length=0;room=1;clears=0;kills=0;maxHp=100;hp=100;coins=24;level=1;xp=34;power=12;armor=4;equipped={weapon:'⚔',armor:'♜',charm:'◈'};roomEnemies=3;roomReady=true;paused=false;updateHUD();for(let i=0;i<roomEnemies;i++)spawnEnemy(room);setEnemyCard(chooseTarget());$('quest-badge').textContent='IN PROGRESS';$('quest-title').textContent='Clear the chamber';$('quest-copy').textContent='The old stones are stirring. Defeat every creature to reveal what lies beyond.'}
function startGame(){gameStarted=true;paused=false;$('start-overlay').classList.add('hidden');resetGame()}
$('start-btn').onclick=startGame;$('continue-btn').onclick=nextRoom;$('again-btn').onclick=()=>{$('end-overlay').classList.add('hidden');$('start-overlay').classList.remove('hidden');gameStarted=false};$('attack-btn').addEventListener('pointerdown',e=>{e.preventDefault();attack()});$('dash-btn').addEventListener('pointerdown',e=>{e.preventDefault();dash()});$('burst-btn').addEventListener('pointerdown',e=>{e.preventDefault();burst()});
addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.code==='Space'||e.code==='Enter')attack();if(e.code==='ShiftLeft'||e.code==='ShiftRight')dash();if(e.code==='KeyQ'||e.code==='KeyE')burst()});addEventListener('keyup',e=>keys[e.code]=false);
const joy=$('joystick'),knob=$('joy-knob');joy.addEventListener('pointerdown',e=>{e.preventDefault();joystickTouch=e.pointerId;joy.setPointerCapture(e.pointerId);updateJoy(e)});joy.addEventListener('pointermove',e=>{if(e.pointerId===joystickTouch)updateJoy(e)});function updateJoy(e){const r=joy.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2;let dx=e.clientX-cx,dy=e.clientY-cy;let l=Math.hypot(dx,dy),max=r.width*.34;if(l>max){dx=dx/l*max;dy=dy/l*max}knob.style.transform=`translate(${dx}px,${dy}px)`;move.x=dx/max;move.z=dy/max}function stopJoy(e){if(e.pointerId===joystickTouch){joystickTouch=null;move.x=0;move.z=0;knob.style.transform=''}}joy.addEventListener('pointerup',stopJoy);joy.addEventListener('pointercancel',stopJoy);
